-- Model: lnk_placement_position__placement_hkey_curr
-- Description: Current active relationship for LNK_PLACEMENT_POSITION using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_PLACEMENT_POSITION_HKEY AS LNK_PLACEMENT_POSITION_HKEY,
    l.PLACEMENT_HKEY AS PLACEMENT_HKEY,
    l.POSITION_HKEY AS POSITION_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.PLACEMENT_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_placement_position') }} l
INNER JOIN {{ ref('lks_bh4sf_placement_position_curr') }} ls
    ON l.LNK_PLACEMENT_POSITION_HKEY = ls.LNK_PLACEMENT_POSITION_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
